TELEMETRY_SDK_LANGUAGE_CPP = "cpp"
#: [.NET](https://opentelemetry.io/docs/languages/dotnet/)
TELEMETRY_SDK_LANGUAGE_DOTNET = "dotnet"
#: [Erlang/Elixir](https://opentelemetry.io/docs/languages/erlang/)
TELEMETRY_SDK_LANGUAGE_ERLANG = "erlang"
#: [Go](https://opentelemetry.io/docs/languages/go/)
TELEMETRY_SDK_LANGUAGE_GO = "go"
#: [Java](https://opentelemetry.io/docs/languages/java/)
TELEMETRY_SDK_LANGUAGE_JAVA = "java"
#: [Kotlin](https://opentelemetry.io/docs/languages/kotlin/)
TELEMETRY_SDK_LANGUAGE_KOTLIN = "kotlin"
#: [Node.js](https://opentelemetry.io/docs/languages/js/)
TELEMETRY_SDK_LANGUAGE_NODEJS = "nodejs"
#: [PHP](https://opentelemetry.io/docs/languages/php/)
TELEMETRY_SDK_LANGUAGE_PHP = "php"
#: [Python](https://opentelemetry.io/docs/languages/python/)
TELEMETRY_SDK_LANGUAGE_PYTHON = "python"
#: [Ruby](https://opentelemetry.io/docs/languages/ruby/)
TELEMETRY_SDK_LANGUAGE_RUBY = "ruby"
#: [Rust](https://opentelemetry.io/docs/languages/rust/)
TELEMETRY_SDK_LANGUAGE_RUST = "rust"
#: [Swift](https://opentelemetry.io/docs/languages/swift/)
TELEMETRY_SDK_LANGUAGE_SWIFT = "swift"
#: [Browser](https://opentelemetry.io/docs/languages/js/)
TELEMETRY_SDK_LANGUAGE_WEBJS = "webjs"

#: The name of the telemetry SDK as defined above.
TELEMETRY_SDK_NAME = "telemetry.sdk.name"

#: The version string of the telemetry SDK.
TELEMETRY_SDK_VERSION = "telemetry.sdk.version"


# Event names (OTLP `LogRecord.event_name`).
#: Namespace of app-defined events, named `custom.<name>` and carrying the app's own attributes.
EVENT_CUSTOM = "custom"
#: OTel GenAI assistant message (also a function call), a span event on `llm_node`.
EVENT_GEN_AI_ASSISTANT_MESSAGE = "gen_ai.assistant.message"
#: OTel GenAI choice, a span event on `llm_node`.
EVENT_GEN_AI_CHOICE = "gen_ai.choice"
#: OTel GenAI system (or developer) message, a span event on `llm_node`.
EVENT_GEN_AI_SYSTEM_MESSAGE = "gen_ai.system.message"
#: OTel GenAI tool message (a function call output), a span event on `llm_node`.
EVENT_GEN_AI_TOOL_MESSAGE = "gen_ai.tool.message"
#: OTel GenAI user message, a span event on `llm_node`.
EVENT_GEN_AI_USER_MESSAGE = "gen_ai.user.message"
#: The app moved to the foreground or background.
EVENT_LK_DEVICE_APP_STATE_CHANGED = "lk.device.app_state.changed"
#: An audio session interruption began or ended.
EVENT_LK_DEVICE_AUDIO_INTERRUPTION = "lk.device.audio.interruption"
#: The audio route changed.
EVENT_LK_DEVICE_AUDIO_ROUTE_CHANGED = "lk.device.audio_route.changed"
#: Charging changed, or the level crossed 20 % or 10 % unplugged.
EVENT_LK_DEVICE_BATTERY_CHANGED = "lk.device.battery.changed"
#: A capture device failed.
EVENT_LK_DEVICE_CAPTURE_FAILED = "lk.device.capture.failed"
#: Low Power Mode changed.
EVENT_LK_DEVICE_LOW_POWER_CHANGED = "lk.device.low_power.changed"
#: Memory pressure changed.
EVENT_LK_DEVICE_MEMORY_CHANGED = "lk.device.memory.changed"
#: The network path changed.
EVENT_LK_DEVICE_NETWORK_CHANGED = "lk.device.network.changed"
#: Thermal state changed.
EVENT_LK_DEVICE_THERMAL_CHANGED = "lk.device.thermal.changed"
#: Pipeline smoke test.
EVENT_LK_PING = "lk.ping"
#: The Room left connected for good.
EVENT_LK_ROOM_DISCONNECTED = "lk.room.disconnected"
#: One RTC stats window for one track and direction.
EVENT_LK_RTC_STATS_SAMPLE = "lk.rtc.stats.sample"
#: Self-telemetry; counts since the previous report.
EVENT_LK_TELEMETRY_REPORT = "lk.telemetry.report"

# Span names.
#: The agent session, parent of every turn. Kind: internal.
SPAN_AGENT_SESSION = "agent_session"
#: The agent's audio playing out. Kind: internal.
SPAN_AGENT_SPEAKING = "agent_speaking"
#: One agent turn (generation), parent of the LLM and TTS nodes. Kind: internal.
SPAN_AGENT_TURN = "agent_turn"
#: Answering-machine detection on an outbound call. Kind: internal.
SPAN_AMD = "amd"
#: Draining an agent activity before it ends. Kind: internal.
SPAN_DRAIN_AGENT_ACTIVITY = "drain_agent_activity"
#: One end-of-utterance inference. Kind: internal.
SPAN_EOU_DETECTION = "eou_detection"
#: The endpointing wait, from the user's last speech to the turn decision. Kind: internal.
SPAN_EOU_WAIT = "eou_wait"
#: A synchronous block on the agent event loop. Kind: internal.
SPAN_EVENT_LOOP_BLOCKED = "event_loop_blocked"
#: One function tool execution, the OTel GenAI execute-tool span. Kind: internal.
SPAN_FUNCTION_TOOL = "function_tool"
#: The job's entrypoint, root of a job's trace. Kind: internal.
SPAN_JOB_ENTRYPOINT = "job_entrypoint"
#: The job shutting down. Kind: internal.
SPAN_JOB_SHUTDOWN = "job_shutdown"
#: One LLM-judge evaluation of the session. Kind: internal.
SPAN_JUDGE_EVALUATION = "judge_evaluation"
#: A keyterm update to the STT. Kind: internal.
SPAN_KEYTERM_DETECTION = "keyterm_detection"
#: One connect attempt. Kind: client.
SPAN_LK_CONNECT = "lk.connect"
#: One track publish. Kind: internal.
SPAN_LK_PUBLISH = "lk.publish"
#: One reconnect cycle. Kind: client.
SPAN_LK_RECONNECT = "lk.reconnect"
#: One subscription, from the intent to subscribe to the first media. Kind: internal.
SPAN_LK_SUBSCRIBE = "lk.subscribe"
#: The LLM fallback adapter choosing an instance. Kind: internal.
SPAN_LLM_FALLBACK_ADAPTER = "llm_fallback_adapter"
#: The agent's LLM node for one generation. Kind: internal.
SPAN_LLM_NODE = "llm_node"
#: One LLM inference request, the OTel GenAI inference span. Kind: client.
SPAN_LLM_REQUEST = "llm_request"
#: The LLM request's stream being consumed. Kind: internal.
SPAN_LLM_REQUEST_RUN = "llm_request_run"
#: A plugin-task metric noted through the Node binding, stamped with its resolved frame. Kind: internal.
SPAN_METRICS = "metrics"
#: The agent's `on_enter` hook. Kind: internal.
SPAN_ON_ENTER = "on_enter"
#: The agent's `on_exit` hook. Kind: internal.
SPAN_ON_EXIT = "on_exit"
#: The session-end hook. Kind: internal.
SPAN_ON_SESSION_END = "on_session_end"
#: The `on_user_turn_completed` hook. Kind: internal.
SPAN_ON_USER_TURN_COMPLETED = "on_user_turn_completed"
#: Pausing an agent activity. Kind: internal.
SPAN_PAUSE_AGENT_ACTIVITY = "pause_agent_activity"
#: Publishing the agent's audio track. Kind: internal.
SPAN_PUBLISH_AUDIO_OUTPUT = "publish_audio_output"
#: One realtime-model generation. Kind: client.
SPAN_REALTIME_INFERENCE = "realtime_inference"
#: Realtime-model metrics attached to a turn. Kind: internal.
SPAN_REALTIME_METRICS = "realtime_metrics"
#: Resuming an agent activity. Kind: internal.
SPAN_RESUME_AGENT_ACTIVITY = "resume_agent_activity"
#: Connecting the job to its room. Kind: client.
SPAN_ROOM_CONNECT = "room_connect"
#: Disconnecting from the room. Kind: client.
SPAN_ROOM_DISCONNECT = "room_disconnect"
#: An outgoing RPC. Kind: client.
SPAN_RPC_CALL = "rpc_call"
#: An incoming RPC handled by the agent. Kind: server.
SPAN_RPC_HANDLER = "rpc_handler"
#: Closing the session. Kind: internal.
SPAN_SESSION_CLOSE = "session_close"
#: Uploading the session report. Kind: internal.
SPAN_SESSION_END_UPLOAD = "session_end_upload"
#: Starting the session (room I/O, first activity). Kind: internal.
SPAN_SESSION_START = "session_start"
#: Initializing the agent's tool sets. Kind: internal.
SPAN_SETUP_TOOLSETS = "setup_toolsets"
#: One shutdown callback. Kind: internal.
SPAN_SHUTDOWN_CALLBACK = "shutdown_callback"
#: Starting an agent activity. Kind: internal.
SPAN_START_AGENT_ACTIVITY = "start_agent_activity"
#: The TTS fallback adapter choosing an instance. Kind: internal.
SPAN_TTS_FALLBACK_ADAPTER = "tts_fallback_adapter"
#: The agent's TTS node for one generation. Kind: internal.
SPAN_TTS_NODE = "tts_node"
#: One TTS request. Kind: client.
SPAN_TTS_REQUEST = "tts_request"
#: The TTS request's stream being consumed. Kind: internal.
SPAN_TTS_REQUEST_RUN = "tts_request_run"
#: The Node binding driving `Tts::stream` (the duplex path). Kind: internal.
SPAN_TTS_STREAM = "tts_stream"
#: The sentence-splitting adapter over a non-streaming TTS. Kind: internal.
SPAN_TTS_STREAM_ADAPTER = "tts_stream_adapter"
#: The Node binding driving `Tts::synthesize` (the simplex path). Kind: internal.
SPAN_TTS_SYNTHESIZE = "tts_synthesize"
#: Replacing the session's agent. Kind: internal.
SPAN_UPDATE_AGENT = "update_agent"
#: The user speaking (VAD). Kind: internal.
SPAN_USER_SPEAKING = "user_speaking"
#: One user turn, from speech to the turn decision. Kind: internal.
SPAN_USER_TURN = "user_turn"
#: Waiting for the participant's audio track. Kind: internal.
SPAN_WAIT_FOR_AUDIO_TRACK = "wait_for_audio_track"
#: Waiting for the participant to link to. Kind: internal.
SPAN_WAIT_FOR_PARTICIPANT = "wait_for_participant"
#: Waiting for the participant's video track. Kind: internal.
SPAN_WAIT_FOR_VIDEO_TRACK = "wait_for_video_track"

# Checkpoint names: span events of the spans above. `lk.reconnect` names its attempts
# `attempt <n> <mode>` instead.
#: The agent state changed (`lk.old_state` -> `lk.new_state`).
CHECKPOINT_AGENT_STATE_CHANGED = "agent_state_changed"
#: The subscriber's SDP answer went out.
CHECKPOINT_ANSWER_SENT = "answer_sent"
#: A peer connection was created before the join response (JS port only).
CHECKPOINT_EARLY_PC_CREATED = "early_pc_created"
#: The RTC engine is ready (Swift stamps it with pc_connected).
CHECKPOINT_ENGINE = "engine"
#: The entrypoint was cancelled.
CHECKPOINT_ENTRYPOINT_CANCELLED = "entrypoint_cancelled"
#: The entrypoint returned.
CHECKPOINT_ENTRYPOINT_RETURNED = "entrypoint_returned"
#: The entrypoint started running.
CHECKPOINT_ENTRYPOINT_STARTED = "entrypoint_started"
#: A synchronous block on the event loop, with `lk.blocking.duration`; mirrors the span of the same name.
CHECKPOINT_EVENT_LOOP_BLOCKED = "event_loop_blocked"
#: The OTel exception event (`exception.*`), recorded on whichever span the exception was caught on; declared here once.
CHECKPOINT_EXCEPTION = "exception"
#: The first frame arrived.
CHECKPOINT_FIRST_FRAME = "first_frame"
#: The first inbound stats reading with bytes; the span ends ok here.
CHECKPOINT_FIRST_MEDIA = "first_media"
#: OTel GenAI inference details event (the GenAI registry defines it; events cannot be referenced
CHECKPOINT_GEN_AI_CLIENT_INFERENCE_OPERATION_DETAILS = "gen_ai.client.inference.operation.details"
#: One generation started (the generation attributes).
CHECKPOINT_GENERATION = "generation"
#: The worker accepted the job.
CHECKPOINT_JOB_ACCEPTED = "job_accepted"
#: The server assigned the job.
CHECKPOINT_JOB_ASSIGNED = "job_assigned"
#: The worker received the job request.
CHECKPOINT_JOB_RECEIVED = "job_received"
#: The server-side job start time, as the worker learned it.
CHECKPOINT_JOB_STARTED_ON_SERVER = "job_started_on_server"
#: The join response arrived.
CHECKPOINT_JOIN_RECV = "join_recv"
#: The publisher's SDP offer went out.
CHECKPOINT_OFFER_SENT = "offer_sent"
#: The linked participant left the room, with `lk.disconnect_reason`.
CHECKPOINT_PARTICIPANT_DISCONNECTED = "participant_disconnected"
#: The session linked to its participant.
CHECKPOINT_PARTICIPANT_LINKED = "participant_linked"
#: The primary peer connection connected.
CHECKPOINT_PC_CONNECTED = "pc_connected"
#: The peer connections exist (stamped once the join is adopted).
CHECKPOINT_PC_CREATED = "pc_created"
#: Pre-connect audio was replayed, with `lk.pre_connect_audio.duration`.
CHECKPOINT_PRE_CONNECT_AUDIO = "pre_connect_audio"
#: A preemptive generation was discarded in favour of this one (`lk.speech_id` of the discarded handle).
CHECKPOINT_PREEMPTIVE_GENERATION_DISCARDED = "preemptive_generation_discarded"
#: A job process was launched for it.
CHECKPOINT_PROCESS_ASSIGNED = "process_assigned"
#: A later trigger re-armed the wait.
CHECKPOINT_REARMED = "rearmed"
#: The Room reached the connected state.
CHECKPOINT_ROOM_CONNECTED = "room_connected"
#: Signaling is up (stamped with ws_open on the web and with join_recv on Swift).
CHECKPOINT_SIGNAL = "signal"
#: The hook stopped the response.
CHECKPOINT_STOP_RESPONSE = "stop_response"
#: The platform reported the remote track subscribed.
CHECKPOINT_SUBSCRIBED = "subscribed"
#: A newer detection superseded this one.
CHECKPOINT_SUPERSEDED = "superseded"
#: The track was subscribed, with `lk.track_sid` and `lk.track_source`.
CHECKPOINT_TRACK_SUBSCRIBED = "track_subscribed"
#: The user spoke again during the wait.
CHECKPOINT_USER_RESUMED = "user_resumed"
#: The user state changed (`lk.old_state` -> `lk.new_state`).
CHECKPOINT_USER_STATE_CHANGED = "user_state_changed"
#: The signaling WebSocket opened.
CHECKPOINT_WS_OPEN = "ws_open"

# Metric names.
#: Time to the first chunk of a streaming GenAI response (deprecated upstream; declared as emitted). Instrument: histogram, unit: `s`.
METRIC_GEN_AI_CLIENT_OPERATION_TIME_TO_FIRST_CHUNK = "gen_ai.client.operation.time_to_first_chunk"
#: Unit of the instrument above, exactly as the producer creates it (empty = none).
METRIC_GEN_AI_CLIENT_OPERATION_TIME_TO_FIRST_CHUNK_UNIT = "s"
#: Input and output tokens used by the GenAI operation (deprecated upstream; declared as emitted). Instrument: histogram, unit: `{token}`.
METRIC_GEN_AI_CLIENT_TOKEN_USAGE = "gen_ai.client.token.usage"
#: Unit of the instrument above, exactly as the producer creates it (empty = none).
METRIC_GEN_AI_CLIENT_TOKEN_USAGE_UNIT = "{token}"
#: Seconds to acquire a provider connection. Instrument: histogram, unit: `s`.
METRIC_LK_AGENTS_CONNECTION_ACQUIRE_TIME = "lk.agents.connection.acquire_time"
#: Unit of the instrument above, exactly as the producer creates it (empty = none).
METRIC_LK_AGENTS_CONNECTION_ACQUIRE_TIME_UNIT = "s"
#: Duration of synchronous blocks detected on an agent event loop. Instrument: histogram, unit: `s`.
METRIC_LK_AGENTS_EVENT_LOOP_BLOCKED_DURATION = "lk.agents.event_loop.blocked_duration"
#: Unit of the instrument above, exactly as the producer creates it (empty = none).
METRIC_LK_AGENTS_EVENT_LOOP_BLOCKED_DURATION_UNIT = "s"
#: End-to-end latency of a turn. Instrument: histogram, unit: `s`.
METRIC_LK_AGENTS_TURN_E2E_LATENCY = "lk.agents.turn.e2e_latency"
#: Unit of the instrument above, exactly as the producer creates it (empty = none).
METRIC_LK_AGENTS_TURN_E2E_LATENCY_UNIT = "s"
#: Delay from the end of speech to the turn decision. Instrument: histogram, unit: `s`.
